const categorias = $json.CATEGORIAS.split(',').map(c => c.trim());
const today = new Date();
const endDate = today.toISOString().split('T')[0];
const startDate = new Date(today.getTime() - 28 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

return categorias.map(cat => ({
  json: {
    categoria: cat,
    startDate,
    endDate,
    config: {
      ANTHROPIC_API_KEY: $json.ANTHROPIC_API_KEY,
      GSC_ACCESS_TOKEN: $json.GSC_ACCESS_TOKEN,
      GSC_SITE_URL: $json.GSC_SITE_URL,
      NOTION_API_KEY: $json.NOTION_API_KEY,
      NOTION_DATABASE_ID: $json.NOTION_DATABASE_ID,
      DISCORD_WEBHOOK_URL: $json.DISCORD_WEBHOOK_URL
    }
  }
}));

const rows = $json.rows || [];
const categoria = $('Split Categorias').item.json.categoria;
const config = $('Split Categorias').item.json.config;

// Palabras clave transaccionales (intención de alquiler/compra)
const intentKeywords = [
  'alquiler', 'alquilar', 'rentar', 'renting',
  'precio', 'presupuesto', 'coste', 'tarifa',
  'cerca', 'madrid', 'barcelona', 'valencia', 'sevilla', 'bilbao',
  'empresa', 'obra', 'industrial',
  'mejor', 'comparativa', 'vs',
  'donde', 'como', 'cual'
];

const transaccionales = rows
  .filter(row => {
    const query = row.keys[0].toLowerCase();
    return intentKeywords.some(kw => query.includes(kw));
  })
  .map(row => ({
    query: row.keys[0],
    page: row.keys[1],
    clicks: row.clicks,
    impressions: row.impressions,
    ctr: (row.ctr * 100).toFixed(2),
    position: row.position.toFixed(1)
  }))
  .sort((a, b) => b.impressions - a.impressions);

// Detectar posibles canibalizaciones (misma query en multiples paginas)
const queryPages = {};
transaccionales.forEach(r => {
  if (!queryPages[r.query]) queryPages[r.query] = [];
  queryPages[r.query].push(r.page);
});
const canibalizaciones = Object.entries(queryPages)
  .filter(([q, pages]) => pages.length > 1)
  .map(([query, pages]) => ({ query, pages, count: pages.length }));

// Keywords con posicion entre 5-20 (oportunidad de mejora)
const oportunidades = transaccionales.filter(r => {
  const pos = parseFloat(r.position);
  return pos >= 5 && pos <= 20;
}).slice(0, 20);

// Keywords que caen (posicion > 10 con muchas impresiones)
const alertas = transaccionales.filter(r => {
  const pos = parseFloat(r.position);
  return pos > 10 && r.impressions > 50;
});

return [{ json: {
  categoria,
  totalKeywords: transaccionales.length,
  transaccionales: transaccionales.slice(0, 30),
  oportunidades,
  canibalizaciones,
  alertas,
  config
} }];

