const analisis = $json.analisis;
const config = $json.config;

const tieneAlertas = analisis.canibalizaciones_detectadas.length > 0 || analisis.alertas_posicion.length > 0;

let canibText = '';
if (analisis.canibalizaciones_detectadas.length > 0) {
  canibText = analisis.canibalizaciones_detectadas.map(c =>
    `  - "${c.query}" -> ${c.paginas_afectadas.length} paginas compitiendo\n    Accion: ${c.accion_recomendada}`
  ).join('\n');
} else {
  canibText = '  Ninguna detectada';
}

let alertText = '';
if (analisis.alertas_posicion.length > 0) {
  alertText = analisis.alertas_posicion.map(a =>
    `  - "${a.keyword}" pos ${a.posicion_actual} (${a.impresiones} imp)\n    Accion: ${a.accion}`
  ).join('\n');
} else {
  alertText = '  Ninguna detectada';
}

const contenidosText = analisis.contenidos_propuestos.slice(0, 5).map((c, i) =>
  `  ${i+1}. [${c.tipo}] ${c.titulo_propuesto} (${c.volumen_estimado})`
).join('\n');

return [{ json: {
  tieneAlertas,
  categoria: analisis.categoria,
  resumen: analisis.resumen_ejecutivo,
  totalContenidos: analisis.contenidos_propuestos.length,
  contenidosText,
  canibText,
  alertText,
  config
} }];

